tool_calls:
cd /home/eval/pkgs; mkdir -p bin build
cat > bin/order <<'EOF'
#!/bin/bash
# usage: order FILE
export LC_ALL=C
[ $# -ge 1 ] || { echo "usage: $0 file" >&2; exit 2; }
awk '
{
  sub(/#.*/, ""); gsub(/\r/, ""); gsub(/[ \t]+/, " ")
  sub(/^ /, ""); sub(/ $/, "")
  if ($0 == "") next
  i = index($0, ":")
  if (i) { lhs = substr($0, 1, i-1); rhs = substr($0, i+1) } else { lhs = $0; rhs = "" }
  gsub(/ /, "", lhs)
  if (lhs == "") next
  pk[lhs] = 1
  n = split(rhs, d, " ")
  for (k = 1; k <= n; k++) {
    pk[d[k]] = 1
    if (!((lhs SUBSEP d[k]) in seen)) {
      seen[lhs, d[k]] = 1
      cnt[lhs]++
      rd[d[k]] = rd[d[k]] " " lhs
    }
  }
}
END {
  # simple sorted ready set via repeated min scan
  np = 0
  for (p in pk) names[++np] = p
  # sort names (insertion via merge-free approach: use external-free heap)
  # binary heap of ready packages
  hs = 0
  for (p in pk) if (cnt[p] == 0) push(p)
  while (hs > 0) {
    p = pop(); print p; done[p] = 1
    m = split(rd[p], r, " ")
    for (k = 1; k <= m; k++) if (--cnt[r[k]] == 0) push(r[k])
  }
  rem = ""; bad = 0
  for (p in pk) if (!(p in done)) { lst[++bad] = p }
  if (bad) {
    # sort lst
    for (a = 2; a <= bad; a++) { v = lst[a]; b = a-1; while (b > 0 && lst[b] > v) { lst[b+1] = lst[b]; b-- } lst[b+1] = v }
    for (a = 1; a <= bad; a++) rem = rem (a>1 ? " " : "") lst[a]
    print "cycle: " rem > "/dev/stderr"
    exit 1
  }
}
function push(x,   i, t) {
  h[++hs] = x; i = hs
  while (i > 1 && h[int(i/2)] > h[i]) { t = h[i]; h[i] = h[int(i/2)]; h[int(i/2)] = t; i = int(i/2) }
}
function pop(   r, i, c, t) {
  r = h[1]; h[1] = h[hs--]; i = 1
  while ((c = 2*i) <= hs) {
    if (c < hs && h[c+1] < h[c]) c++
    if (h[i] <= h[c]) break
    t = h[i]; h[i] = h[c]; h[c] = t; i = c
  }
  return r
}
' "$1"
EOF
chmod +x bin/order
bin/order deps.txt > build/order.txt
bin/order deps-big.txt > build/big-order.txt
bin/order deps-cycle.txt > build/cycle-order.txt 2> build/cycle.txt; echo $? > build/cycle.rc
for f in build/*; do echo == $f; cat $f; done; cat deps-big.txt

